import sys, optax
sys.path.append('storage/noema/submissions')
from dual_path_hybrid_motif_heads_regcal import build_network

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        "learning_rate": 0.001,
        "weight_decay": 0.01,
        "grad_clip": 0.45,
    }

def create_network(hparams):
    # Pass through all hparams (network uses defaults for architecture; heads remain unchanged)
    return build_network(hparams.get('d_output', 1), hparams.get('task_type', 'regression'), hparams)

def create_optimizer(learning_rate: float = 0.001, weight_decay: float = 0.01):
    return optax.chain(
        optax.clip_by_global_norm(0.45),
        optax.adamw(learning_rate=learning_rate, weight_decay=weight_decay)
    )

def complete(params, opt_state, trial_data):
    ds = trial_data.get('dataset'); vm = trial_data.get('val_metric')
    print(f"[Complete] {ds} val_metric={vm}")
